BEGIN TRANSACTION READ ONLY;with q as(select value->>'title' title,value->>'originalTitle' original,value->>'author' author from jsonb_array_elements('[{"title":"Beladen huis","author":"Christien Brinkgreve"},{"title":"Je bent prachtig","originalTitle":"Hello Beautiful","author":"Ann Napolitano"},{"title":"Liften naar de hemel","author":"Lex Paleaux"},{"title":"De verborgen belofte","author":"Lucinda Riley"},{"title":"De Zoete Zusjes zijn de baas","author":"Hanneke de Zoete"},{"title":"Winterengel","author":"Corina Bomann"},{"title":"Wurgcontract","author":"Loes den Hollander"},{"title":"Wondermond","author":"Anne-Gine Goemans"},{"title":"Ik ga leven","author":"Lale Gül"},{"title":"Films die nergens draaien","author":"Yorick Goldewijk"},{"title":"Krekel","author":"Annet Schaap"},{"title":"De Franse dochter","author":"Soraya Lane"},{"title":"Het geschenk","author":"Gaea Schoeters"},{"title":"Grondwerk","author":"Tijl Nuyts"},{"title":"Als de dieren","author":"Lieselot Mariën"},{"title":"De rode koe","author":"Hans Depelchin"},{"title":"De mensheid zal nog van mij horen","author":"Joris van Casteren"},{"title":"Dius","author":"Stefan Hertmans"},{"title":"De Resten","author":"Toni Coppers"},{"title":"Wachten op Noah","author":"Ish Ait Hamou"},{"title":"De heks","author":"Freida McFadden"},{"title":"Een winter vol verrassingen","author":"Santa Montefiore"},{"title":"De lamzak","author":"Herman Brusselmans"},{"title":"Sluipmoord","author":"Robert Bryndza"},{"title":"Bankgeheim","author":"Jonas Boets"},{"title":"Grote kleine waarheid","author":"Liane Moriarty"},{"title":"De vrouw van mijn echtgenoot","author":"Carla Kovach"},{"title":"Een toekomst in Montmartre","author":"Marie Lacrosse"},{"title":"Het C.R.U.I.S.E. complot","author":"Timon Verbeeck"},{"title":"In de puree","author":"Bieke Biesbrouck"}]'::jsonb)), matched as(select distinct w.id from public.works w join public.authors a on a.id=w.author_id where exists(select 1 from q where lower(w.title)=lower(q.title)or lower(w.title)=lower(q.original)or lower(a.name)=lower(q.author)) or exists(select 1 from public.catalog_work_title_aliases t join q on lower(t.title)=lower(q.title) where t.work_id=w.id))select jsonb_build_object('project','qvplwejffhjvxaypmjut','at',now(),'works',(select coalesce(jsonb_agg(to_jsonb(w)order by id),'[]')from public.works w where id in(select id from matched)),'authors',(select coalesce(jsonb_agg(to_jsonb(a)order by id),'[]')from public.authors a where id in(select author_id from public.works where id in(select id from matched))),'editions',(select coalesce(jsonb_agg(to_jsonb(e)order by id),'[]')from public.editions e where work_id in(select id from matched)),'aliases',(select coalesce(jsonb_agg(to_jsonb(t)order by work_id,title),'[]')from public.catalog_work_title_aliases t where work_id in(select id from matched))) snapshot;COMMIT;
